INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('9f056477-1012-430c-8baa-34f319ed675e', 'Vigencia', E'La fecha de entrega de contrato es el 30 de enero de 2023, pero se ejercitaron las 2 prórrogas de 90 de días, terminando en la entrega en julio de 2023, afectando a la vigencia\n\n"Fin de la Vigencia del Contrato de Arrendamiento. 5 (cinco) años posteriores a la expiración del Plazo de Gracia y/o las prórrogas correspondientes."', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('9f056477-1012-430c-8baa-34f319ed675e', 'Domicilio del Contrato', E'Vía José López Portillo No. 338, Fraccionamiento Parque Residencial Coacalco 1ra Sección, Coacalco de Berriozabal, Estado de México\nLocal número SA-01', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('9f056477-1012-430c-8baa-34f319ed675e', 'Fecha de Apertura', '30 de marzo de 2024', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('9f056477-1012-430c-8baa-34f319ed675e', 'Fecha de Firma del Contrato', '31 de agosto de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('9f056477-1012-430c-8baa-34f319ed675e', 'Late Fees', '13', '17', 'INTERESES MORATORIOS', E'- If rent is not paid on time, the landlord can charge late fees.\n- The late fee is an additional 10% per month on the overdue amount.\n- This fee applies for each month or part of a month the payment is late.', 'La falta del pago oportuno de la renta estipulada dentro del plazo señalado, dará derecho a la Arrendadora a cobrar intereses moratorios a razón del 10% (diez por ciento) mensual adicional de su importe por el simple retraso, por cada mes o fracción en que incurra en mora.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('9f056477-1012-430c-8baa-34f319ed675e', 'Incremento de Renta', '6', '5', 'AJUSTE DE LA RENTA', E'- The monthly rent will increase every year starting from July 2023.\n- The increase will occur on each anniversary of the lease start date.\n- The rent increase will match the percentage increase of the National Consumer Price Index (INPC).\n- The INPC is published by the National Institute of Statistics and Geography in the Official Gazette.\n- The increase is based on the INPC for the 12 months prior to the rent increase date.', 'Las Partes convienen que la Renta Mensual será incrementada anualmente, contado a partir de la fecha de entrega (julio de 2023) y así subsecuentemente cada aniversario de la fecha durante toda la vigencia del arrendamiento, en el mismo porcentaje de incremento del Índice Nacional de Precios al Consumidor (INPC) que publique el Intitulo Nacional de Estadística y Geografía en el Diario Oficial de la Federación para el periodo de 12 (doce) meses inmediato anterior a la fecha en que deba incrementarse la renta mensual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('9f056477-1012-430c-8baa-34f319ed675e', 'Common Area Maintenance Charges', '9', '10', 'A).- GASTOS DE ADMINISTRACIÓN Y MANTENIMIENTO', E'- The Tenant must pay the Landlord an administration and maintenance fee equal to 5% of the Monthly Rent plus VAT.\n- This fee is calculated based on the current rent amount at the time the payment is due.\n- The Tenant cannot request an account of how these fees are used or influence the management or maintenance decisions of the Shopping Center.\n- The Landlord is required to use these funds to maintain, repair, and replace parts of the Shopping Center to keep it in good working condition.', 'La Arrendataria se obliga a cubrir a la Arrendadora por concepto de gastos de administración y mantenimiento una cantidad equivalente al 5% del importe de la Renta Mensual más el impuesto al valor agregado. Cada pago mensual por este concepto será calculado sobre el importe de la renta vigente a la fecha en que sea exigible dicho pago. La Arrendataria acepta expresamente que no tendrá derecho a exigir rendición de cuentas respecto a las cantidades que pague por dichos conceptos, ni podrá intervenir para determinar el tipo o las características de la administración o mantenimiento del Centro Comercial, sin embargo, la Arrendadora tendrá la obligación de usar los fondos para mantener, reparar y reemplazar el Centro Comercial y los elementos del mismo para mantenerlos en óptimas condiciones de funcionamiento.');
INSERT INTO locations (id, nombre, brand_id, company_id, address1, address2, city, state, zip, country, full_address, latitude, longitude, location_type, location_subtype, business_category, business_type, property_name, square_meters, total_leased_sqm, total_subleased_sqm, atributos_extra) VALUES ('36d541f3-9478-42f3-ba03-3c1bd8a71a53', 'Encuentro Oceanía', '43a59b98-494b-4f44-a59a-ad5bb1b79127', '83602737-ca9f-417e-b1ac-19d0ad371be6', '355 Avenida Del Peñón', 'N3 Y N4', 'Moctezuma Segunda Sección, Venustiano Carranza', 'Ciudad de México', '15530', 'MX', '355 Avenida Del Peñón, N3 Y N4, Moctezuma Segunda Sección, Venustiano Carranza, Ciudad de México 15530', 19.4395919211, -99.0940074443, 'Retail', 'Strip Center', 'Sports & Recreation', 'Franchise', 'Encuentro Oceania', 2437.68, 2437.68, NULL, '{"map_lease_expiration_date":"2033-06-13","map_marker_color":"#A879D2","coordinate":"point|19.4395919211|-99.0940074443|accurate","city_state":"Moctezuma Segunda Sección, Venustiano Carranza, Ciudad de México","company_name":"Fitness Para Todos, S. de R.L. de C.V.","location_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"landlord_company_full_address":"Avenida De Las Palmas 239, Piso 6, Lomas De Chapultepec, Miguel Hidalgo, Ciudad De México 11000","tenant_company_full_address":"Calzada De Los Leones 170 Piso 1, Alvaro Obregon, CDMX 01010","tenant_company_addr1":"Calzada De Los Leones 170 Piso 1","tenant_company_city":"Alvaro Obregon","tenant_company_state":"CDMX","tenant_company_zip":"01010","tenant_company_country":"MX","lease_currency":{"id":"mexican_peso","label":"Mexican peso","symbol":"$","code":"MXN","default":false},"next_option_expiration_date":"2038-06-13","lease_expiration_date":"2033-06-13","lease_renewal_notice":"180 Days Prior","lease_length_in_months_remaining":80,"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57557,"grid_name":"Encuentro Oceanía","grid_full_address":"355 Avenida Del Peñón, N3 Y N4, Moctezuma Segunda Sección, Venustiano Carranza, Ciudad de México 15530","map_addr_1":"355 Avenida Del Peñón","map_addr_2":"N3 Y N4","map_city_state_zip":"Moctezuma Segunda Sección, Venustiano Carranza, Ciudad de México 15530","grid_brand":"Planet Fitness","location_created_at":"2025-09-24 16:10:43","active_lease_count_over_time":50755,"location_count_over_time":57557,"remaining_rent_liability_over_time":50755}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('17b4fe75-c6bb-45c7-aa39-420d6cb8974d', '36d541f3-9478-42f3-ba03-3c1bd8a71a53', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Encuentro Oceanía Lease: CIBANCO S.A., Fidecomiso CIB/548 (05/31/2022 - 06/13/2033)', NULL, false, 'activo', 'Lease', NULL, '2023-06-13', '2023-02-13', '2033-06-13', '2043-06-13', false, 2, NULL, 2, NULL, NULL, '2032-12-15', 'Send Notice to Decline', 132, 'CIBANCO S.A., Fidecomiso CIB/548', NULL, NULL, 'Avenida De Las Palmas 239', 'Piso 6', 'Lomas De Chapultepec, Miguel Hidalgo', 'Ciudad De México', '11000', 'MX', NULL, NULL, NULL, 150, 'percent', NULL, 411967.92, 823935.84, 'Cantidad que se aplicará a los primeros 2 (dos) meses contados a partir de la fecha en que el Arrendatario tiene la obligación de pago es decir en la Fecha de Inicio de pago de la Renta.', NULL, false, '{"lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('17b4fe75-c6bb-45c7-aa39-420d6cb8974d', 'Domicilio del Contrato', E'Avenida del Peñón número 355, Colonia Moctezuma, Segunda Sección, Alcaldía Venustiano Carranza, en la Ciudad de México, C.P. 15530\nLocal comercial identificado como N3 y N4', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('17b4fe75-c6bb-45c7-aa39-420d6cb8974d', 'Fecha de Apertura', '9 de septiembre de 2023', 'America Gonzalez', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('17b4fe75-c6bb-45c7-aa39-420d6cb8974d', 'Fecha de Firma del Contrato', '31 de mayo de 2022', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('17b4fe75-c6bb-45c7-aa39-420d6cb8974d', 'Late Fees', '13', '6', 'INTERÉS MORATORIO', E'- If the Tenant does not pay the Rent or any other amount owed on time, they must pay the Landlord a penalty.\n- This penalty is calculated by tripling the Interbank Equilibrium Interest Rate set by the Bank of Mexico for 28-day operations in national currency, as published in the Official Gazette.', 'Para el caso de que el ARRENDATARIO no pague la Renta dentro del término pactado en el presente Contrato o cualquier otra cantidad a su cargo, pagará a favor del ARRENDADOR la cantidad que resulte de multiplicar por 3 (tres) la Tasa de Interés Interbancaria de Equilibrio que determine el Banco de México para operaciones denominadas en moneda nacional, a plazo de 28 (veintiocho) días, publicada en el Diario Oficial de la Federación.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('17b4fe75-c6bb-45c7-aa39-420d6cb8974d', 'Incremento de Renta', '13', '5', 'INCREMENTOS DE RENTA', E'- The rent will increase every 12 months starting from the opening date.\n- The increase will match the inflation rate in Mexico, based on the National Consumer Price Index.\n- The increase will be calculated using the rent from the previous year.\n- The annual rent increase will not exceed 8% of the current monthly rent.\n- If inflation exceeds 10%, the parties will renegotiate the contract terms.', 'Los contratantes convienen que la renta pactada en la cláusula tercera será incrementada cada 12 (doce) meses, contados a partir de la Fecha de Apertura cantidad que aumentará en la misma proporción que la inflación de los Estados Unidos Mexicanos, para lo cual se tomará como base el Índice Nacional de Precios al Consumidor publicado por el Instituto Nacional de Estadística y Geografía (o el índice que le sustituya para medir la inflación en los Estados Unidos Mexicanos), durante los 12 (doce) meses anteriores a la fecha del incremento o bien el índice que lo sustituya, en el entendido que los incrementos de la Renta se realizarán tomando como base la última renta del año inmediato anterior. En la inteligencia de que dichos aumentos anuales no serán mayor al 8% (ocho por ciento) de la Renta Mensual Vigente, siempre que este porcentaje no rebase el 10% (diez por ciento) de ser así y si el INPC incrementa en más del 10% (diez por ciento) Las partes renegociarán los términos comerciales del presente Contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('17b4fe75-c6bb-45c7-aa39-420d6cb8974d', 'Common Area Maintenance Charges', '23', '23', 'MANTENIMIENTO', E'- The monthly maintenance fee is $30.00 MXN per square meter plus VAT, totaling $60,473.10 MXN plus VAT.\n- The tenant is responsible for keeping common areas clean and well-maintained.\n- If the tenant causes any damage, they must repair it within 15 days of receiving written notice from the landlord.\n- If the tenant fails to make repairs, the landlord can fix the damage and charge the tenant, using the tenant''s security deposit if necessary.', E'La cuota de mantenimiento mensual será la cantidad de $30.00 (treinta pesos 00/100 M.N.) mas I.V.A. por metro cuadrado es decir la cantidad de $60,473.10 (sesenta mil cuatrocientos setenta y tres pesos 10/100 M.N.) más el correspondiente Impuesto al Valor Agregado (la "Cuota de Mantenimiento Mensual").\n\nSerá responsabilidad del "ARRENDATARIO" procurar la limpieza, conservación y buena imagen de las áreas comunes del Centro Comercial así como el debido mantenimiento de todas aquellas áreas a que se refiere el párrafo anterior, obligándose a reparar cualquier desperfecto, en caso de que se compruebe que fue su responsabilidad, en dicha área en un plazo máximo de 15 (quince) días contados a partir de la notificación que haga por escrito el "ARRENDADOR" al "ARRENDATARIO” al respecto, de no hacerlo, el "ARRENDADOR" tendrá el derecho de realizarlo con recursos propios y a cargo y por cuenta del "ARRENDATARIO", autorizando desde este momento al "ARRENDADOR" del uso de la cantidad que como depósito en garantía entrega el “ARRENDATARIO".');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('17b4fe75-c6bb-45c7-aa39-420d6cb8974d', 'Cuota de Inscripción', '4', '7', 'CUOTA DE INSCRIPCIÓN', E'- Total amount: $4,809,169.32 plus VAT.\n- Payment schedule:\n  - 50% ($2,404,584.66 plus VAT) due within 60 days after signing the Addendum.\n  - Remaining 50% ($2,404,584.66 plus VAT) due within 15 days after the delivery of the Commercial Space.', 'La cantidad equivalente a $4,809,169.32 (cuatro millones ochocientos nueve mil ciento sesenta y nueve pesos 32/100 M.N.) más el Impuesto al Valor Agregado, la cual se pagará de la siguiente manera: a) el equivalente al 50%, es decir la cantidad de $2,404,584.66 (dos millones cuatrocientos cuatro mil quinientos ochenta y cuatro pesos 66/100 M.N.) mas I.V.A., a más tardar 60 (sesenta) días posteriores a la fecha de firma del presente Addendum y b) el equivalente al 50% restante, es decir la cantidad de $2,404,584.66 (dos millones cuatrocientos cuatro mil quinientos ochenta y cuatro pesos 66/100 M.N.) mas I.V.A., a más tardar 15 (quince) días posteriores a la entrega del Local Comercial');
