,"lease_is_silent":"No","rtr_enabled":1,"grid_id":57562,"grid_name":"Cuatro Caminos","grid_full_address":"30 Calzada Transmisiones Militares, AN-01A, Naucalpan De Juárez, Mexico 53370","map_addr_1":"30 Calzada Transmisiones Militares","map_addr_2":"AN-01A","map_city_state_zip":"Naucalpan De Juárez, Mexico 53370","grid_brand":"Planet Fitness","location_created_at":"2025-09-24 16:29:32","active_lease_count_over_time":50767,"location_count_over_time":57562,"remaining_rent_liability_over_time":50767,"base_rent_current_month":"394546.0000","cam_current_month":"31563.6800","publicidad_current_month":"7890.9200","base_rent_next_month":"394546.0000","cam_next_month":"31563.6800","publicidad_next_month":"7890.9200","base_rent_per_square_meter":"2400.00","cam_per_square_meter":"192.00","publicidad_per_square_meter":"48.00","base_rent_per_year":"4734552.0000","cam_per_year":"378764.1600","publicidad_per_year":"94691.0400"}'::jsonb);
